///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dupCheck = $c.util.getComponent('dupCheck');
        scwin.upd_attachFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles"]');
        scwin.upd_attachFiles_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_2"]');
        scwin.upd_attachFiles_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_3"]');
        scwin.upd_attachFiles_4 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_4') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_4"]');
        scwin.upd_attachFiles_5 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_5') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_5"]');
        scwin.upd_attachFiles_6 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_6') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_6"]');
        scwin.upd_attachFiles_7 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_7') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_7"]');
        scwin.upd_attachFiles_8 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_8') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_8"]');
        scwin.upd_attachFiles_9 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_9') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_9"]');
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf55001.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_bdchrgRegNoFileInstYn", fn: function () { return String(String((dma_pageContext.get("bdchrgRegNoFileInstYn") ?? ""))); } },
        { childId: "ipt_fromWhere", fn: function () { return String(String((dma_pageContext.get("fromWhere") ?? ""))); } },
        { childId: "ipt_checkIdYn", fn: function () { return String(String((dma_pageContext.get("checkIdYn") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        if ($c.util.getComponent('ipt_fromWhere').getValue() === "login") {
            if ($c.util.getComponent('ipt_checkIdYn').getValue() === "N") {
                $c.util.getComponent('ipt_newYn').setValue("Y");
                scwin.dupCheck.setStyle("display", "none");
                (($c.util.getComponent('ipt_integUsrId')) && ($c.util.getComponent('ipt_integUsrId')).setReadOnly ? ($c.util.getComponent('ipt_integUsrId')).setReadOnly((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
                const div = $("#corpFileList");
                if (div.is(":visible")) {
                    div.setStyle("display", "none");
                } else {
                    div.setStyle("display", "");
                }
            } else {
                $("input[name=ipt_integUsrId]").focus().select();
            }
            $c.util.getComponent('ipt_bdchrgApplTpCd').setValue("N");
            await $c.win.alert("신고담당자(정/부) 등록이 필요합니다.");
        } else {
            $("input[name=ipt_integUsrId]").focus().select();
            $c.util.getComponent('ipt_bdchrgApplTpCd').setValue("R");
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf55001.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

