            return false;
        }
        if ($c.util.getComponent(["ipt_belngDepNm", "ipt_belngDepNm_2"][i]).getValue() === "") {
            await $c.win.alert("신고담당자 소속부서를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.util.getComponent(["ipt_telNo2", "ipt_telNo2_2"][i]).getValue() === "") {
            await $c.win.alert("신고담당자 전화번호를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.util.getComponent(["ipt_telNo3", "ipt_telNo3_2"][i]).getValue() === "") {
            await $c.win.alert("신고담당자 전화번호를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.util.getComponent(["ipt_encrypCellphoneNo1", "ipt_encrypCellphoneNo1_2"][i]).getValue() === "") {
            await $c.win.alert("신고담당자 휴대전화번호를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.util.getComponent(["ipt_encrypCellphoneNo2", "ipt_encrypCellphoneNo2_2"][i]).getValue() === "") {
            await $c.win.alert("신고담당자 휴대전화번호를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.util.getComponent(["ipt_encrypCellphoneNo3", "ipt_encrypCellphoneNo3_2"][i]).getValue() === "") {
            await $c.win.alert("신고담당자 휴대전화번호를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.util.getComponent(["ipt_encrypEmail1", "ipt_encrypEmail1_2"][i]).getValue() === "") {
            await $c.win.alert("신고담당자 이메일을 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.util.getComponent(["ipt_encrypEmail2", "ipt_encrypEmail2_2"][i]).getValue() === "") {
            await $c.win.alert("신고담당자 이메일을 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    if ("Y" !== $c.util.getComponent("dma_registerMemberReq").get("bdchrgRegNoFileInstYn")) {
        const attach_file = document.getElementsByName("bdchrg_appl_doc_cd");
        const div = $("#corpFileList");
        let startIdx = 0;
        if (div.is(":visible")) {
            startIdx = 0;
        } else {
            startIdx = 3;
        }
        for (let i = startIdx; i < attach_file.length; i++) {
            if ($("input[name='attach_file_nm[" + i + "]']").val() === "") {
                await $c.win.alert("필수 첨부파일을 입력하세요.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name downloadDoc
 * @description download Doc 처리
 * @param {String} docCd docCd
 * @param {String} fileNm fileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.downloadDoc = async function (docCd, fileNm) {
    if (!await $c.win.confirm(fileNm + " 다운로드 하시겠습니까?")) {
        return;
    }
    $c.util.getComponent("dma_registerMemberReq").set("contnId", docCd);
    await scwin.tx_fn_downloadDoc('/main/notice.do?method=downloadFile');
    return;
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancel = async function () {
    if ($c.util.getComponent('ipt_fromWhere').getValue() === "login") {
        await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /main/logout.do?method=logout). 전환 대상 화면이 확정되면 연결됩니다.');
    } else {
        $c.win.closePopup();
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name checkUsrIdDone
 * @description check Usr Id Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.checkUsrIdDone = function (data) {
    const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_message').setValue(result.message);
    $c.util.getComponent('ipt_newYn').setValue(result.newYn);
};

/**
 * @method
 * @name checkUsrId
 * @description check Usr Id 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkUsrId = async function () {
    const r = await scwin.tx_fn_checkUsrId();
    try {
        scwin.checkUsrIdDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf55001.fn_checkUsrId' });
    }
    return r;
};
